using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using UnityEngine.AI;
namespace DeliveryService.Mok.Editor {
[InitializeOnLoad] public static class ConspiracyStoryInstaller {
 static ConspiracyStoryInstaller(){EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling||!File.Exists("Temp/Conspiracy-request"))return;var cmd=File.ReadAllText("Temp/Conspiracy-request").Trim();File.Delete("Temp/Conspiracy-request");try{if(cmd=="apply")Apply();else if(cmd=="refine")Refine();else Inspect();}catch(Exception e){File.WriteAllText("Logs/Conspiracy-result.txt",e.ToString());}}
 static Scene Main(){var s=SceneManager.GetSceneByPath(StoryTutorialBuilder.Main);if(!s.isLoaded)s=EditorSceneManager.OpenScene(StoryTutorialBuilder.Main,OpenSceneMode.Additive);return s;}
 static Transform Anchor(Transform root,string name,Vector3 point){var t=new GameObject(name).transform;t.SetParent(root,false);t.position=point;return t;}
 static Vector3 Sample(Vector3 p){if(NavMesh.SamplePosition(p,out var hit,14,NavMesh.AllAreas))return hit.position;throw new Exception("No navigation at "+p);}
 static Vector3 Along(Vector3[] corners,float distance){for(int i=1;i<corners.Length;i++){float length=Vector3.Distance(corners[i-1],corners[i]);if(distance<=length)return Vector3.Lerp(corners[i-1],corners[i],distance/length);distance-=length;}return corners[corners.Length-1];}
 static GameObject Box(Transform root,string name,Vector3 at,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(root,false);g.transform.localPosition=at;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;return g;}
 static GameObject Fit(Transform root,string path,string name,Vector3 at,Vector3 size,Material mat=null){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(path),root);g.name=name;g.transform.localPosition=Vector3.zero;g.transform.localRotation=Quaternion.identity;var renderers=g.GetComponentsInChildren<Renderer>();var b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);g.transform.localScale=Vector3.Scale(g.transform.localScale,new Vector3(size.x/Mathf.Max(.01f,b.size.x),size.y/Mathf.Max(.01f,b.size.y),size.z/Mathf.Max(.01f,b.size.z)));b=renderers[0].bounds;foreach(var r in renderers)b.Encapsulate(r.bounds);g.transform.position+=root.TransformPoint(at)-b.center;foreach(var c in g.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(c);if(mat)foreach(var r in renderers)r.sharedMaterials=r.sharedMaterials.Select(_=>mat).ToArray();return g;}
 static void Apply(){
 var scene=Main();SceneManager.SetActiveScene(scene);var dir="Logs/Conspiracy-"+DateTime.Now.ToString("yyyyMMdd-HHmmss");Directory.CreateDirectory(dir);EditorSceneManager.SaveScene(scene,dir+"/Before.unity",true);
 var m=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VenueFinale>(true)).Single();var broker=m.preparation.preparation.delivery.broker;
 m.overheard=ConspiracyDialogue.Overheard();m.closing=ConspiracyDialogue.Closing();
 broker.endingLines[0]="실장: 회수하라는 지시는 박진웅에게 직접 받았어. 조직의 실세야. 그런데 임무가 끝나자 명령을 전달한 나까지 없애려 해. 이유는 그놈이 알겠지.";
 var story=AssetDatabase.LoadAssetAtPath<PrologueStory>("Assets/Scripts/Mok/Prologue/Art/BankPrologueStory.asset");File.Copy(AssetDatabase.GetAssetPath(story),dir+"/PrologueStory.asset",true);var defaults=ScriptableObject.CreateInstance<PrologueStory>();story.vault.text=defaults.vault.text;story.carConversation=defaults.carConversation;story.shopConversation=defaults.shopConversation;story.getaway.text=defaults.getaway.text;EditorUtility.SetDirty(story);UnityEngine.Object.DestroyImmediate(defaults);
 var plan=AssetDatabase.LoadAssetAtPath<NightPreparationPlan>("Assets/Scripts/Mok/ShopUI/FirstChapterPreparation.asset");File.Copy(AssetDatabase.GetAssetPath(plan),dir+"/Preparation.asset",true);plan.premise=ConspiracyDialogue.Premise;foreach(var item in plan.missions){if(item.id=="broker")item.description="연락이 끊겼던 실장이 자신을 제거하려는 조직을 피해 만나자고 문자를 보냈습니다. 약속한 날 밤에 찾아가 함께 탈출하세요.";if(item.id=="finale"){item.description="피자 배달원으로 행사장에 잠입해 박진웅의 계획을 확인하세요. 발각되면 준비한 차량으로 탈출하고, 민기와 함께 노출된 매장을 떠나야 합니다.";item.result="조직 간 충돌과 두목 자리 탈취 계획 확인 · 매장 탈출 · 감옥 챕터 도입";}}EditorUtility.SetDirty(plan);
 foreach(var surface in scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Unity.AI.Navigation.NavMeshSurface>(true)))if(surface.navMeshData)surface.AddData();
 if(m.aftermath&&!m.aftermath.prison){UnityEngine.Object.DestroyImmediate(m.aftermath.gameObject);m.aftermath=null;}
 if(!m.aftermath){
  var root=new GameObject("CHAPTER / 매장 탈출과 감옥 도입");SceneManager.MoveGameObjectToScene(root,scene);var a=root.AddComponent<ShopEscapeChapter>();m.aftermath=a;a.mission=m;a.mingi=m.preparation.preparation.delivery.kitchen.actor;
  var agent=a.mingi.GetComponent<NavMeshAgent>()??a.mingi.gameObject.AddComponent<NavMeshAgent>();agent.enabled=false;agent.radius=.3f;agent.height=1.8f;agent.baseOffset=0;
  a.doorway=m.preparation.preparation.delivery.kitchen.guideRoute;var start=Sample(m.preparation.preparation.delivery.kitchen.outsideStand.position);var end=Sample(broker.meeting.position);var path=new NavMeshPath();if(!NavMesh.CalculatePath(start,end,NavMesh.AllAreas,path)||path.status!=NavMeshPathStatus.PathComplete)throw new Exception("Shop escape route is disconnected");float total=0;for(int i=1;i<path.corners.Length;i++)total+=Vector3.Distance(path.corners[i-1],path.corners[i]);if(total<70)throw new Exception("Shop escape route too short");
  a.route=new[]{Anchor(root.transform,"골목으로 이동",Along(path.corners,22)),Anchor(root.transform,"조직원 돌파",Along(path.corners,55)),Anchor(root.transform,"경찰 포위 지점",Along(path.corners,Mathf.Min(total-5,105)))};
  a.ambush=new[]{Anchor(root.transform,"추격 출현 1",Sample(start+Vector3.right*8)),Anchor(root.transform,"추격 출현 2",Sample(start-Vector3.forward*8)),Anchor(root.transform,"추격 출현 3",Sample(a.route[1].position+Vector3.right*8)),Anchor(root.transform,"추격 출현 4",Sample(a.route[1].position-Vector3.forward*8))};
  var grey=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Prologue/Art/YamazakiOffice/Warm grey plaster.mat");var metal=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Prologue/Art/YamazakiOffice/Graphite steel.mat");if(!grey||!metal)throw new Exception("Missing office materials");
  var bag=Box(root.transform,"비상 가방",m.safePoint.position+Vector3.right*.7f+Vector3.up*.3f,new Vector3(.55f,.28f,.3f),metal);a.bag=bag.transform;Box(bag.transform,"손잡이",new Vector3(0,.65f,0),new Vector3(.45f,.2f,.15f),metal);
  var blockade=new GameObject("출동 경찰 포위");blockade.transform.SetParent(root.transform,false);a.policeBlock=blockade;
  a.police=new Transform[4];for(int i=0;i<4;i++){var cop=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/Scripts/Min/Prefab/NPC/Police.prefab"),blockade.transform);cop.name="체포 연출 경찰 "+i;foreach(var comp in cop.GetComponentsInChildren<MonoBehaviour>(true))UnityEngine.Object.DestroyImmediate(comp);foreach(var comp in cop.GetComponentsInChildren<NavMeshAgent>(true))UnityEngine.Object.DestroyImmediate(comp);foreach(var comp in cop.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(comp);foreach(var comp in cop.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(comp);cop.transform.position=Sample(a.route[2].position+new Vector3(i%2==0?-2:2,0,i<2?-5:5));a.police[i]=cop.transform;}
  var jail=new GameObject("챕터 2 도입 / 구치소");jail.transform.SetParent(root.transform,false);jail.transform.position=new Vector3(2200,0,2200);a.prison=jail;
  Box(jail.transform,"바닥",new Vector3(0,-.15f,0),new Vector3(8,.3f,8),grey);Box(jail.transform,"천장",new Vector3(0,3.3f,0),new Vector3(8,.3f,8),grey);
  const string wall="Assets/Synty/PolygonHeist/Prefab/Environment/SM_Env_Wall_Interior_Ground_01.prefab";
  foreach(float x in new[]{-4f,4f}){Fit(jail.transform,wall,"Synty 측면 벽",new Vector3(x,1.6f,0),new Vector3(.25f,3.2f,8),grey);Box(jail.transform,"벽 충돌",new Vector3(x,1.6f,0),new Vector3(.25f,3.2f,8),grey);}
  Fit(jail.transform,wall,"Synty 뒤 벽",new Vector3(0,1.6f,-4),new Vector3(8,3.2f,.25f),grey);Box(jail.transform,"뒤 벽 충돌",new Vector3(0,1.6f,-4),new Vector3(8,3.2f,.25f),grey);
  for(float x=-3.9f;x<4;x+=.32f)Box(jail.transform,"철창",new Vector3(x,1.6f,3.6f),new Vector3(.055f,3.2f,.07f),metal);foreach(float y in new[]{.15f,1.5f,3.1f})Box(jail.transform,"철창 보강대",new Vector3(0,y,3.6f),new Vector3(8,.07f,.08f),metal);
  var barrier=Box(jail.transform,"철창 충돌",new Vector3(0,1.6f,3.6f),new Vector3(8,3.2f,.08f),metal);barrier.GetComponent<Renderer>().enabled=false;
  Fit(jail.transform,"Assets/Synty/PolygonCity/Prefabs/Props/SM_Prop_ParkBench_01.prefab","Synty 수용실 벤치",new Vector3(-2,.45f,-2.8f),new Vector3(2.6f,.9f,.7f),metal);
  Box(jail.transform,"복도 바닥",new Vector3(0,-.15f,5.6f),new Vector3(8,.3f,4),grey);Box(jail.transform,"복도 끝벽",new Vector3(0,1.6f,7.6f),new Vector3(8,3.2f,.25f),grey);
  for(int i=0;i<2;i++){var light=new GameObject("구치소 조명").AddComponent<Light>();light.transform.SetParent(jail.transform,false);light.transform.localPosition=new Vector3(0,2.7f,i==0?0:5.5f);light.type=LightType.Point;light.range=10;light.intensity=1.4f;light.color=new Color(.83f,.9f,1);}
  a.prisonArrival=Anchor(jail.transform,"플레이어 도착",jail.transform.position+new Vector3(1,.05f,1));a.prisonArrival.rotation=Quaternion.Euler(0,210,0);a.prisonMingi=Anchor(jail.transform,"민기 도착",jail.transform.position+new Vector3(-1,.05f,-.6f));a.prisonMingi.rotation=Quaternion.Euler(0,45,0);
  EditorUtility.SetDirty(a);
  File.WriteAllText("Logs/Conspiracy-route.txt","NavMesh route length "+total+"\n"+string.Join("\n",a.route.Select(t=>t.name+" "+t.position)));
 }
 EditorUtility.SetDirty(broker);EditorUtility.SetDirty(m);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Logs/Conspiracy-result.txt","PASS story, scene and chapter bridge saved; backup "+dir);
 }
 static void Refine(){var scene=Main();EditorSceneManager.SaveScene(scene,"Logs/Conspiracy-before-refine-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".unity",true);var a=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<ShopEscapeChapter>(true)).Single();var wallMat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scripts/Mok/Prologue/Art/YamazakiOffice/Warm grey plaster.mat");if(!a.prison.transform.Find("복도 천장")){Box(a.prison.transform,"복도 천장",new Vector3(0,3.3f,5.6f),new Vector3(8,.3f,4),wallMat);foreach(float x in new[]{-4f,4f})Box(a.prison.transform,"복도 옆벽",new Vector3(x,1.6f,5.6f),new Vector3(.25f,3.2f,4),wallMat);}a.prisonArrival.localPosition=new Vector3(1,.05f,-1);a.prisonArrival.localRotation=Quaternion.Euler(0,315,0);a.prisonMingi.localPosition=new Vector3(-1,.05f,1);a.prisonMingi.localRotation=Quaternion.Euler(0,135,0);foreach(var r in a.prison.GetComponentsInChildren<MeshRenderer>(true))if(r.name=="벽 충돌"||r.name=="뒤 벽 충돌")r.enabled=false;EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText("Logs/Conspiracy-result.txt","PASS prison framing and wall layers refined");}
 static void Inspect(){var s=Main();var m=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<VenueFinale>(true)).Single();var b=m.preparation.preparation.delivery.broker;var k=m.preparation.preparation.delivery.kitchen;File.WriteAllText("Logs/Conspiracy-inspect.txt","safe "+m.safePoint.position+" entry "+m.entry.position+" exit "+b.exit.position+" meet "+b.meeting.position+" kitchen "+k.actor.position+" return "+m.preparation.preparation.delivery.returnPoint.position+"\nMingi components "+string.Join(",",k.actor.GetComponents<MonoBehaviour>().Select(c=>c.GetType().Name)));foreach(var n in s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Unity.AI.Navigation.NavMeshSurface>(true)))File.AppendAllText("Logs/Conspiracy-inspect.txt","\nNAV "+n.name+" type "+n.agentTypeID+" data "+(n.navMeshData?n.navMeshData.sourceBounds.ToString():"null"));for(int i=0;i<NavMesh.GetSettingsCount();i++){int id=NavMesh.GetSettingsByIndex(i).agentTypeID;bool ok=NavMesh.SamplePosition(m.safePoint.position,out var h,50,new NavMeshQueryFilter{agentTypeID=id,areaMask=NavMesh.AllAreas});File.AppendAllText("Logs/Conspiracy-inspect.txt","\nSAMPLE "+id+" "+ok+" "+h.position);}File.WriteAllText("Logs/Conspiracy-result.txt","inspect done");}
}}
